pub fn decodeHex(allocator: std.mem.Allocator, text: []const u8) ![]u8 {
    const bytes = try allocator.alloc(u8, text.len / 2);
    errdefer allocator.free(bytes);
    _ = try std.fmt.hexToBytes(bytes, text);
    return bytes;
}
pub fn patternAlloc(allocator: std.mem.Allocator, pattern: []const u8, length: usize) ![]u8 {
    const bytes = try allocator.alloc(u8, length);
    for (bytes, 0..) |*byte, i| byte.* = pattern[i % pattern.len];
    return bytes;
}
