pub fn indexStart(bytes: []const u8) usize {
    const backward = std.mem.readInt(u32, bytes[bytes.len - 8 ..][0..4], .little);
    return bytes.len - 12 - (@as(usize, backward) + 1) * 4;
}
pub const Location = struct { header: usize, data: usize, check: usize, end: usize };
pub fn locations(bytes: []const u8, output: []Location) !usize {
    const stream = try container.parseStreamHeader(bytes);
    const check_len: usize = switch (stream.check) {
        .none => 0,
        .crc32 => 4,
        .crc64 => 8,
        .sha256 => 32,
        else => return error.UnsupportedXzFeature,
    };
    var pos: usize = 12;
    var count: usize = 0;
    while (bytes[pos] != 0) {
        const header_start = pos;
        const header_len = (@as(usize, bytes[pos]) + 1) * 4;
        const header = try container.parseIncrementalBlockHeader(bytes[pos..][0..header_len]);
        pos += header_len;
        const data = pos;
        while (true) {
            const control = bytes[pos];
            if (control == 0) {
                pos += 1;
                break;
            }
            if (control <= 2) {
                const length = @as(usize, std.mem.readInt(u16, bytes[pos + 1 ..][0..2], .big)) + 1;
                pos += 3 + length;
            } else {
                const prefix: usize = if ((control >> 5) & 3 >= 2) 6 else 5;
                const length = @as(usize, std.mem.readInt(u16, bytes[pos + 3 ..][0..2], .big)) + 1;
                pos += prefix + length;
            }
        }
        const padding = (4 - ((header.header_size + pos - data) % 4)) % 4;
        const check = pos + padding;
        pos = check + check_len;
        if (count >= output.len) return error.OutputLimitExceeded;
        output[count] = .{ .header = header_start, .data = data, .check = check, .end = pos };
        count += 1;
    }
    return count;
}
