    try std.testing.expect(workspace.peakWorkingMemoryBytes() >= sum);
    if (wrapped) |allocator| {
        const ledger: *std.testing.FailingAllocator = @ptrCast(@alignCast(allocator.ptr));
        try std.testing.expectEqual(ledger.allocated_bytes - ledger.freed_bytes, workspace.workingMemoryBytes());
    }
}

